package com.shikshasetu.ai;
import jakarta.annotation.PostConstruct;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import weka.core.SerializationHelper;import java.nio.file.*;import java.util.Optional;
@Component public class AiModelRuntime {private final Path path;private volatile ModelBundle current;public AiModelRuntime(@Value("${shikshasetu.ai.model-path:./data/ai-models/student-deterioration.model}") String p){path=Paths.get(p).toAbsolutePath().normalize();}@PostConstruct public void load(){if(!Files.exists(path))return;try{Object x=SerializationHelper.read(path.toString());if(x instanceof ModelBundle b)current=b;}catch(Exception e){throw new IllegalStateException("Could not load saved AI model: "+e.getMessage(),e);}}public Optional<ModelBundle> current(){return Optional.ofNullable(current);}public synchronized void install(ModelBundle b){current=b;}public Path path(){return path;}}
